      family: model && model.userData ? model.userData.entityFamily : "unknown",
      ageInTicks: 0,
      walkAnimationPos: 0,
      walkAnimationSpeed: 0,
      walkAnimationSpeedOld: 0,
      walkAnimationScale: 1,
      speedValue: 1,
      pitch: 0,
      isCrouching: false,
      isFallFlying: false,
      swimAmount: 0,
      bodyYaw: 0,
      attackTime: 0,
      tentacleAngle: 0,
      squidXBodyRot: 0,
      squidZBodyRot: 0,
      previousPosition: null
